import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"VeilChat — Serverless P2P Messenger","description":"A P2P messenger with end-to-end encryption in pure Python: X25519 handshake, ChaCha20-Poly1305 frames, LAN discovery. No servers, no accounts, no metadata.","frontmatter":{"title":"VeilChat — Serverless P2P Messenger","description":"A P2P messenger with end-to-end encryption in pure Python: X25519 handshake, ChaCha20-Poly1305 frames, LAN discovery. No servers, no accounts, no metadata."},"headers":[],"relativePath":"en/projects/veilchat/index.md","filePath":"en/projects/veilchat/index.md"}`),a={name:`en/projects/veilchat/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="veilchat-—-serverless-p2p-messenger" tabindex="-1">VeilChat — Serverless P2P Messenger <a class="header-anchor" href="#veilchat-—-serverless-p2p-messenger" aria-label="Permalink to “VeilChat — Serverless P2P Messenger”">​</a></h1><p><strong><a href="https://github.com/Godde3s/veilchat" target="_blank" rel="noreferrer">VeilChat</a></strong> is my answer to a question I kept hearing: <em>who knows that we are talking?</em> Every mainstream messenger still needs infrastructure that can log who talked to whom and when. VeilChat removes that layer entirely — two peers open a <strong>direct TCP connection</strong>, run a mutually-authenticated key exchange, and talk over an encrypted channel that never touches a third party.</p><h2 id="the-cryptography" tabindex="-1">The cryptography <a class="header-anchor" href="#the-cryptography" aria-label="Permalink to “The cryptography”">​</a></h2><p>I implemented a Noise-inspired handshake from standard primitives — no homemade math:</p><ul><li><strong>Long-term identity</strong> — an X25519 key at <code>~/.veilchat/identity.key</code>, whose SHA-256 fingerprint humans compare out-of-band.</li><li><strong>Forward secrecy</strong> — every connection mixes three DH results (<code>ee</code>, <code>es</code>, <code>se</code>) through HKDF-SHA256 with fresh ephemeral keys, so later key compromise cannot decrypt past sessions.</li><li><strong>Mutual authentication</strong> — a transcript MAC over the handshake binds both static identities; a man in the middle cannot compute it.</li><li><strong>Frame sealing</strong> — ChaCha20-Poly1305 with per-direction keys, monotonically rising nonces and direction-bound AAD, plus a 4 MiB frame cap against floods.</li></ul><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> veilchat</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># terminal 1 — announce on the LAN and wait</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">veilchat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> listen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># terminal 2 — find peers and connect</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">veilchat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">veilchat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connect</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.20</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bob</span></span></code></pre></div><h2 id="engineering-notes" tabindex="-1">Engineering notes <a class="header-anchor" href="#engineering-notes" aria-label="Permalink to “Engineering notes”">​</a></h2><p>The interesting part was not the crypto — it was making asyncio behave: one listener accepts exactly one session, the handshake is written so both roles share one code path (with mirrored transcript ordering — the bug class that silently breaks handshakes), and the session layer multiplexes message/typing/ping/file frames to callbacks. UDP beacons handle LAN discovery, and the crypto, wire-format and transport layers are fully separated, so swapping TCP for WebRTC data channels touches no crypto code.</p><p><strong>8 unit + integration tests</strong> cover key agreement, tamper detection, nonce discipline and a live two-peer exchange on localhost. MIT licensed.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};